import { defineStore } from 'pinia'
import { ref, computed } from 'vue'

export const useCheckInStore = defineStore('checkIn', () => {
  // State
  const isKioskMode = ref(false)
  const apiEndpoint = ref('')
  const submissionHistory = ref([])
  const customerType = ref(null)
  const foundCustomer = ref(null)
  const ticketData = ref(null)

  // Getters
  const isOnline = computed(() => navigator.onLine)
  const lastSubmission = computed(() => 
    submissionHistory.value[submissionHistory.value.length - 1]
  )

  // Actions
  function setKioskMode(enabled) {
    isKioskMode.value = enabled
  }

  function setApiEndpoint(endpoint) {
    apiEndpoint.value = endpoint
  }

  function addSubmission(record) {
    submissionHistory.value.push(record)
  }

  function clearHistory() {
    submissionHistory.value = []
  }

  function setCustomerType(type) {
    customerType.value = type
  }

  function setFoundCustomer(customer) {
    foundCustomer.value = customer
  }

  function clearCustomerData() {
    customerType.value = null
    foundCustomer.value = null
  }

  function setTicketData(data) {
    ticketData.value = data
  }

  function clearTicketData() {
    ticketData.value = null
  }

  return {
    isKioskMode,
    apiEndpoint,
    submissionHistory,
    isOnline,
    lastSubmission,
    customerType,
    foundCustomer,
    ticketData,
    setKioskMode,
    setApiEndpoint,
    addSubmission,
    clearHistory,
    setCustomerType,
    setFoundCustomer,
    clearCustomerData,
    setTicketData,
    clearTicketData,
  }
})

import { ref, onMounted, onUnmounted } from 'vue'
import { useWakeLock } from './useWakeLock'

export function useKioskMode() {
  const isKioskMode = ref(false)
  const { requestWakeLock, releaseWakeLock } = useWakeLock()

  // Prevent context menu
  const preventContextMenu = (e) => {
    e.preventDefault()
  }

  // Prevent text selection
  const preventSelection = () => {
    document.body.style.userSelect = 'none'
    document.body.style.webkitUserSelect = 'none'
  }

  // Enable kiosk mode
  const enableKioskMode = async () => {
    isKioskMode.value = true

    // Request wake lock
    await requestWakeLock()

    // Prevent context menu
    document.addEventListener('contextmenu', preventContextMenu)

    // Prevent text selection
    preventSelection()

    // Hide scrollbars
    document.body.style.overflow = 'hidden'

    // Prevent pull-to-refresh
    document.body.style.overscrollBehavior = 'none'
  }

  // Disable kiosk mode
  const disableKioskMode = () => {
    isKioskMode.value = false

    // Release wake lock
    releaseWakeLock()

    // Remove event listeners
    document.removeEventListener('contextmenu', preventContextMenu)

    // Restore default behaviors
    document.body.style.userSelect = ''
    document.body.style.webkitUserSelect = ''
    document.body.style.overflow = ''
    document.body.style.overscrollBehavior = ''
  }

  onMounted(() => {
    // Auto-enable kiosk mode on mount
    enableKioskMode()
  })

  onUnmounted(() => {
    disableKioskMode()
  })

  return {
    isKioskMode,
    enableKioskMode,
    disableKioskMode,
  }
}

import { ref } from 'vue'

// RepairShopr configuration
const BASE_URL = 'https://mobilemeit.repairshopr.com/api/v1'
const API_KEY = 'T02f7d6e85f7e22f89-b728266fec1b9d61f375cde115ea392e'

export function useRepairShopr() {
  const isLoading = ref(false)
  const error = ref(null)

  async function fetchRepairShopr(endpoint, options = {}) {
    const url = `${BASE_URL}${endpoint}`

    const response = await fetch(url, {
      ...options,
      headers: {
        'Authorization': API_KEY,
        'Accept': 'application/json',
        'Content-Type': 'application/json',
        ...options.headers
      }
    })

    if (!response.ok) {
      const errorText = await response.text()
      let errorMessage = `HTTP ${response.status}`
      try {
        const errorData = JSON.parse(errorText)
        errorMessage = errorData.message || errorData.error || errorMessage
      } catch {
        errorMessage = errorText || errorMessage
      }
      throw new Error(errorMessage)
    }

    return response.json()
  }

  async function createCustomer(customerData) {
    isLoading.value = true
    error.value = null

    try {
      const result = await fetchRepairShopr('/customers', {
        method: 'POST',
        body: JSON.stringify({
          firstname: customerData.firstName,
          lastname: customerData.lastName,
          email: customerData.email,
          phone: customerData.phone,
          business_name: customerData.businessName || '',
          get_sms: true,
          opt_out: false,
          disabled: false,
          no_email: false
        })
      })
      return result.customer
    } catch (err) {
      error.value = err.message
      throw err
    } finally {
      isLoading.value = false
    }
  }

  async function searchCustomers(query) {
    isLoading.value = true
    error.value = null

    try {
      const result = await fetchRepairShopr(`/search?query=${encodeURIComponent(query)}`)
      return result.results || []
    } catch (err) {
      error.value = err.message
      throw err
    } finally {
      isLoading.value = false
    }
  }

  async function findCustomerByEmail(email) {
    const results = await searchCustomers(email)
    return results.find(r => 
      r.table?._type === 'customer' && 
      r.table?._source?.table?.email?.toLowerCase() === email.toLowerCase()
    )?.table?._source?.table
  }

  async function findCustomerByPhone(phone) {
    const cleanPhone = phone.replace(/\D/g, '')
    const results = await searchCustomers(phone)
    return results.find(r => {
      if (r.table?._type !== 'customer') return false
      const customerPhones = r.table?._source?.table?.phones || []
      return customerPhones.some(p => p.number.replace(/\D/g, '') === cleanPhone)
    })?.table?._source?.table
  }

  return {
    isLoading,
    error,
    createCustomer,
    searchCustomers,
    findCustomerByEmail,
    findCustomerByPhone
  }
}

import { useForm, useField } from 'vee-validate'
import * as yup from 'yup'

export function useFormValidation() {
  const schema = yup.object({
    firstName: yup.string()
      .required('First name is required')
      .min(2, 'Must be at least 2 characters')
      .max(50, 'Must be less than 50 characters'),
    lastName: yup.string()
      .required('Last name is required')
      .min(2, 'Must be at least 2 characters')
      .max(50, 'Must be less than 50 characters'),
    email: yup.string()
      .required('Email is required')
      .email('Please enter a valid email address'),
    phone: yup.string()
      .required('Phone number is required')
      .matches(/^\+?[\d\s-()]+$/, 'Please enter a valid phone number')
      .min(10, 'Please enter a valid phone number'),
    serialNumber: yup.string()
      .min(3, 'Serial number must be at least 3 characters'),
  })

  const { handleSubmit, errors, isSubmitting, resetForm } = useForm({
    validationSchema: schema,
  })

  const { value: firstName } = useField('firstName')
  const { value: lastName } = useField('lastName')
  const { value: email } = useField('email')
  const { value: phone } = useField('phone')
  const { value: serialNumber } = useField('serialNumber')

  return {
    firstName,
    lastName,
    email,
    phone,
    serialNumber,
    errors,
    isSubmitting,
    handleSubmit,
    resetForm,
  }
}

import { useForm, useField } from 'vee-validate'
import * as yup from 'yup'

export function useTicketFormValidation() {
  const schema = yup.object({
    caseTitle: yup.string()
      .required('Case title is required')
      .min(3, 'Must be at least 3 characters')
      .max(100, 'Must be less than 100 characters'),
    isUnderWarranty: yup.string()
      .required('Please specify if the system is under warranty')
      .oneOf(['yes', 'no'], 'Please select yes or no'),
    description: yup.string()
      .required('Description is required')
      .min(10, 'Please provide at least 10 characters')
      .max(500, 'Must be less than 500 characters'),
    unitSerialNumber: yup.string()
      .required('Unit serial number is required')
      .min(3, 'Serial number must be at least 3 characters'),
  })

  const { handleSubmit, errors, isSubmitting, resetForm } = useForm({
    validationSchema: schema,
  })

  const { value: caseTitle } = useField('caseTitle')
  const { value: isUnderWarranty } = useField('isUnderWarranty')
  const { value: description } = useField('description')
  const { value: unitSerialNumber } = useField('unitSerialNumber')

  return {
    caseTitle,
    isUnderWarranty,
    description,
    unitSerialNumber,
    errors,
    isSubmitting,
    handleSubmit,
    resetForm,
  }
}

